import React from 'react';

import { TileConcreteDisplayProps } from './TileAbstractDisplay.js';
import { CanvasCircleRenderer } from '../renderers/CanvasCircleRenderer.js';

export const CanvasCircleDisplay = (props: TileConcreteDisplayProps) => {
  const {
    center: { x, y },
    fillColor,
    width,
  } = props;
  // Having several circles with no gap between them creates a visual illusion of
  // circles overlapping.
  const adjustedWidth = width - 1;
  const halfWidth = adjustedWidth / 2;

  return (
    <CanvasCircleRenderer
      x={x}
      y={y}
      radius={halfWidth}
      fillColor={fillColor}
      strokeColor="transparent"
    />
  );
};

CanvasCircleDisplay['displayName'] = 'CanvasCircleDisplay';
